mapper.select:
SELECT
id, event_id, consumer_name, outbox_event_id, event_type,
aggregate_type, aggregate_id, status, retry_count,
locked_by, locked_until, last_error, replay_count,
last_replay_by, last_replay_time, create_time,
update_time, processed_time
FROM tb_inbox_event


        AND consumer_name = #{query.consumerName}


        AND event_id = #{query.eventId}


        AND event_type = #{query.eventType}


        AND aggregate_type = #{query.aggregateType}


        AND aggregate_id = #{query.aggregateId}


        AND status = #{query.status}


        AND create_time >= #{query.createTimeStart}


        AND create_time <= #{query.createTimeEnd}


ORDER BY create_time DESC, id DESC

mapper.delete:
DELETE FROM tb_inbox_event
WHERE status = 'SUCCESS'
  AND processed_time < #{before}
